function student_assessment_reply(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');echo json_encode(array_merge(['success'=>$status>=200&&$status<300],$data),JSON_UNESCAPED_UNICODE|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
function assessment_key(array $question):array{$key=json_decode((string)($question['answer_key_json']??''),true);return is_array($key)?$key:[];}
function assessment_answer_text($value):string{if(is_array($value)||is_object($value))return '';return trim((string)$value);}
function assessment_grade(PDO $pdo,array $question,$answer,float $points,float $negative):array{
  $type=(string)$question['question_type'];$key=assessment_key($question);$options=$pdo->prepare('SELECT id,is_correct,sort_order,option_text,match_value FROM quiz_options WHERE question_id=? ORDER BY sort_order,id');$options->execute([$question['id']]);$all=$options->fetchAll(PDO::FETCH_ASSOC);$earned=0.0;$correct=null;$manual=false;
  if(in_array($type,['multiple_choice','mcq','true_false','image_based','clinical_case'],true)&&$all){$selected=(int)$answer;$opt=null;foreach($all as $row)if((int)$row['id']===$selected)$opt=$row;$correct=(bool)($opt['is_correct']??false);if($correct)$earned=$points;elseif($selected&&$negative>0)$earned=-min($points,$negative);}
  elseif($type==='multiple_select'){$selected=array_values(array_unique(array_map('intval',is_array($answer)?$answer:[])));$truth=array_map('intval',array_column(array_filter($all,static fn($o)=>(int)$o['is_correct']===1),'id'));$correctCount=count($truth);if($correctCount){$right=count(array_intersect($truth,$selected));$wrong=count(array_diff($selected,$truth));$earned=max(0,($right/$correctCount)*$points-min($points,$wrong*$negative));$correct=$wrong===0&&$right===$correctCount;}}
  elseif($type==='ordering'){$expected=$key['sequence']??array_map('intval',array_column($all,'id'));$selected=is_array($answer)?array_map('intval',$answer):[];$matches=0;foreach($expected as $i=>$id)if(isset($selected[$i])&&(string)$selected[$i]===(string)$id)$matches++;$earned=count($expected)?$points*$matches/count($expected):0;$correct=$matches===count($expected)&&$matches>0;}
  elseif($type==='matching'){$expected=$key['pairs']??[];if(!$expected)foreach($all as $option)if($option['match_value']!==null&&$option['match_value']!=='')$expected[(string)$option['id']]=$option['match_value'];$selected=is_array($answer)?$answer:[];$matches=0;foreach($expected as $left=>$right)if(isset($selected[$left])&&(string)$selected[$left]===(string)$right)$matches++;$earned=count($expected)?$points*$matches/count($expected):0;$correct=$matches===count($expected)&&$matches>0;}
  elseif(in_array($type,['short_answer','fill_blank'],true)){$accepted=$key['accepted_answers']??$key['answers']??[];if(!is_array($accepted))$accepted=[$accepted];$value=mb_strtolower(assessment_answer_text($answer),'UTF-8');$correct=$value!==''&&in_array($value,array_map(static fn($v)=>mb_strtolower(trim((string)$v),'UTF-8'),$accepted),true);if($correct)$earned=$points;}
  elseif($type==='essay'||$type==='clinical_case'){$manual=assessment_answer_text($answer)!=='';$correct=$manual?null:false;}
  else{$manual=true;$correct=null;}
  return ['earned'=>round(max(-$points,$earned),2),'correct'=>$correct,'manual'=>$manual];
}

